commit 9e1758efbd68c8b1d27e17e2abe4444e110f3ebe
Author: Willy Tarreau <w@1wt.eu>
Date:   Tue Jun 16 16:32:59 2020 +0200

    BUG/MEDIUM: cfgparse: use parse_line() to expand/unquote/unescape config lines

    Issue 22689 in oss-fuzz shows that specially crafted config files can take
    a long time to process. This happens when variable expansion, backslash
    escaping or unquoting causes calls to memmove() and possibly to realloc()
    resulting in O(N^2) complexity with N following the line size.

    By using parse_line() we now have a safe parser that remains in O(N)
    regardless of the type of operation. Error reporting changed a little bit
    since the errors are not reported anymore from the deepest parsing level.
    As such we now report the beginning of the error. One benefit is that for
    many invalid character sequences, the original line is shown and the first
    bad char or sequence is designated with a caret ('^'), which tends to be
    visually easier to spot, for example:

      [ALERT] 167/170507 (14633) : parsing [mini5.cfg:19]: unmatched brace in environment variable name below:
        "${VAR"}
          ^
    or:

      [ALERT] 167/170645 (14640) : parsing [mini5.cfg:18]: unmatched quote below:
        timeout client 10s'
                          ^

    In case the target buffer is too short for the new line, the output buffer
    is grown in 1kB chunks and kept till the end, so that it should not happen
    too often.

    Before this patch a test like below involving a 4 MB long line would take
    138s to process, 98% of which were spent in __memmove_avx_unaligned_erms(),
    and now it takes only 65 milliseconds:

      $ perl -e 'print "\"\$A\""x1000000,"\n"' | ./haproxy -c -f /dev/stdin 2>/dev/null

    This may be backported to stable versions after a long period of
    observation to be sure nothing broke. It relies on patch "MINOR: tools:
    add a new configurable line parse, parse_line()".

diff --git a/src/cfgparse.c b/src/cfgparse.c
index a9d863e2c..87787a362 100644
--- a/src/cfgparse.c
+++ b/src/cfgparse.c
@@ -1850,6 +1850,9 @@ int readcfgfile(const char *file)
        struct cfg_section *cs = NULL, *pcs = NULL;
        struct cfg_section *ics;
        int readbytes = 0;
+       char *outline = NULL;
+       size_t outlen = 0;
+       size_t outlinesize = 0;

        if ((thisline = malloc(sizeof(*thisline) * linesize)) == NULL) {
                ha_alert("parsing [%s] : out of memory.\n", file);
@@ -1867,8 +1870,6 @@ next_line:
                char *end;
                char *args[MAX_LINE_ARGS + 1];
                char *line = thisline;
-               int dquote = 0;  /* double quote */
-               int squote = 0;  /* simple quote */

                linenum++;

@@ -1897,225 +1898,83 @@ next_line:

                readbytes = 0;

+               /* kill trailing LF */
+               *(end - 1) = 0;
+
                /* skip leading spaces */
                while (isspace((unsigned char)*line))
                        line++;

-
                if (*line == '[') {/* This is the beginning if a scope */
                        err_code |= cfg_parse_scope(file, linenum, line);
                        goto next_line;
                }

-               arg = 0;
-               args[arg] = line;
+               while (1) {
+                       uint32_t err;
+                       char *errptr;

-               while (*line && arg < MAX_LINE_ARGS) {
-                       if (*line == '"' && !squote) {  /* double quote outside single quotes */
-                               if (dquote)
-                                       dquote = 0;
-                               else
-                                       dquote = 1;
-                               memmove(line, line + 1, end - line);
-                               end--;
-                       }
-                       else if (*line == '\'' && !dquote) { /* single quote outside double quotes */
-                               if (squote)
-                                       squote = 0;
-                               else
-                                       squote = 1;
-                               memmove(line, line + 1, end - line);
-                               end--;
-                       }
-                       else if (*line == '\\' && !squote) {
-                       /* first, we'll replace \\, \<space>, \#, \r, \n, \t, \xXX with their
-                        * C equivalent value. Other combinations left unchanged (eg: \1).
-                        */
-                               int skip = 0;
-                               if (line[1] == ' ' || line[1] == '\\' || line[1] == '#') {
-                                       *line = line[1];
-                                       skip = 1;
-                               }
-                               else if (line[1] == 'r') {
-                                       *line = '\r';
-                                       skip = 1;
-                               }
-                               else if (line[1] == 'n') {
-                                       *line = '\n';
-                                       skip = 1;
-                               }
-                               else if (line[1] == 't') {
-                                       *line = '\t';
-                                       skip = 1;
-                               }
-                               else if (line[1] == 'x') {
-                                       if ((line + 3 < end) && ishex(line[2]) && ishex(line[3])) {
-                                               unsigned char hex1, hex2;
-                                               hex1 = toupper(line[2]) - '0';
-                                               hex2 = toupper(line[3]) - '0';
-                                               if (hex1 > 9) hex1 -= 'A' - '9' - 1;
-                                               if (hex2 > 9) hex2 -= 'A' - '9' - 1;
-                                               *line = (hex1<<4) + hex2;
-                                               skip = 3;
-                                       }
-                                       else {
-                                               ha_alert("parsing [%s:%d] : invalid or incomplete '\\x' sequence '%.*s' in '%s'.\n", file, linenum, 4, line, args[0]);
-                                               err_code |= ERR_ALERT | ERR_FATAL;
-                                               goto next_line;
-                                       }
-                               } else if (line[1] == '"') {
-                                       *line = '"';
-                                       skip = 1;
-                               } else if (line[1] == '\'') {
-                                       *line = '\'';
-                                       skip = 1;
-                               } else if (line[1] == '$' && dquote) { /* escaping of $ only inside double quotes */
-                                       *line = '$';
-                                       skip = 1;
-                               }
-                               if (skip) {
-                                       memmove(line + 1, line + 1 + skip, end - (line + skip));
-                                       end -= skip;
-                               }
-                               line++;
-                       }
-                       else if ((!squote && !dquote && *line == '#') || *line == '\n' || *line == '\r') {
-                               /* end of string, end of loop */
-                               *line = 0;
-                               break;
+                       arg = MAX_LINE_ARGS;
+                       outlen = outlinesize;
+                       err = parse_line(line, outline, &outlen, args, &arg,
+                                        PARSE_OPT_ENV | PARSE_OPT_DQUOTE | PARSE_OPT_SQUOTE |
+                                        PARSE_OPT_BKSLASH | PARSE_OPT_SHARP, &errptr);
+
+                       if (err & PARSE_ERR_QUOTE) {
+                               ha_alert("parsing [%s:%d]: unmatched quote below:\n"
+                                        "  %s\n  %*s\n", file, linenum, line, (int)(errptr-line+1), "^");
+                               err_code |= ERR_ALERT | ERR_FATAL;
+                               goto next_line;
                        }
-                       else if (!squote && !dquote && isspace((unsigned char)*line)) {
-                               /* a non-escaped space is an argument separator */
-                               *line++ = '\0';
-                               while (isspace((unsigned char)*line))
-                                       line++;
-                               args[++arg] = line;
-                       }
-                       else if (dquote && *line == '$') {
-                               /* environment variables are evaluated inside double quotes */
-                               char *var_beg;
-                               char *var_end;
-                               char save_char;
-                               char *value;
-                               int val_len;
-                               int newlinesize;
-                               int braces = 0;
-
-                               var_beg = line + 1;
-                               var_end = var_beg;
-
-                               if (*var_beg == '{') {
-                                       var_beg++;
-                                       var_end++;
-                                       braces = 1;
-                               }

-                               if (!isalpha((unsigned char)*var_beg) && *var_beg != '_') {
-                                       ha_alert("parsing [%s:%d] : Variable expansion: Unrecognized character '%c' in variable name.\n", file, linenum, *var_beg);
-                                       err_code |= ERR_ALERT | ERR_FATAL;
-                                       goto next_line; /* skip current line */
-                               }
+                       if (err & PARSE_ERR_BRACE) {
+                               ha_alert("parsing [%s:%d]: unmatched brace in environment variable name below:\n"
+                                        "  %s\n  %*s\n", file, linenum, line, (int)(errptr-line+1), "^");
+                               err_code |= ERR_ALERT | ERR_FATAL;
+                               goto next_line;
+                       }

-                               while (isalnum((unsigned char)*var_end) || *var_end == '_')
-                                       var_end++;
-
-                               save_char = *var_end;
-                               *var_end = '\0';
-                               value = getenv(var_beg);
-                               *var_end = save_char;
-                               val_len = value ? strlen(value) : 0;
-
-                               if (braces) {
-                                       if (*var_end == '}') {
-                                               var_end++;
-                                               braces = 0;
-                                       } else {
-                                               ha_alert("parsing [%s:%d] : Variable expansion: Mismatched braces.\n", file, linenum);
-                                               err_code |= ERR_ALERT | ERR_FATAL;
-                                               goto next_line; /* skip current line */
-                                       }
-                               }
+                       if (err & PARSE_ERR_VARNAME) {
+                               ha_alert("parsing [%s:%d]: forbidden first char in environment variable name below:\n"
+                                        "  %s\n  %*s\n", file, linenum, line, (int)(errptr-line+1), "^");
+                               err_code |= ERR_ALERT | ERR_FATAL;
+                               goto next_line;
+                       }

-                               newlinesize = (end - thisline) - (var_end - line) + val_len + 1;
+                       if (err & PARSE_ERR_HEX) {
+                               ha_alert("parsing [%s:%d]: truncated or invalid hexadecimal sequence below:\n"
+                                        "  %s\n  %*s\n", file, linenum, line, (int)(errptr-line+1), "^");
+                               err_code |= ERR_ALERT | ERR_FATAL;
+                               goto next_line;
+                       }

-                               /* if not enough space in thisline */
-                               if (newlinesize  > linesize) {
-                                       char *newline;
+                       if (err & PARSE_ERR_TOOMANY) {
+                               ha_alert("parsing [%s:%d]: too many words, truncating at word %d, position %ld: <%s>.\n",
+                                        file, linenum, arg, (long)(args[arg-1] - thisline + 1), args[arg-1]);
+                               err_code |= ERR_ALERT | ERR_FATAL;
+                               goto next_line;
+                       }

-                                       newline = realloc(thisline, newlinesize * sizeof(*thisline));
-                                       if (newline == NULL) {
-                                               ha_alert("parsing [%s:%d] : Variable expansion: Not enough memory.\n", file, linenum);
-                                               err_code |= ERR_ALERT | ERR_FATAL;
-                                               goto next_line; /* slip current line */
commit 32234e751320b60a3879f274d4a4753d7570e757
Author: Willy Tarreau <w@1wt.eu>
Date:   Tue Jun 16 17:14:33 2020 +0200

    BUG/MEDIUM: cfgparse: stop after a reasonable amount of fatal error

    One issue with the config parser is that while it tries to report as many
    errors as possible at once, it's actually unbounded. Thus, when calling
    haproxy on a wrong file, it can take ages to process, such as here on
    half a gigabyte of map file instead of config file:

      $ time ./haproxy -c -f large.map 2>&1 |wc -l
      16777220

      real    0m31.324s
      user    0m22.595s
      sys     0m28.909s

    This patch modifies readcfgfile() to stop reading the config file after a
    reasonable amount of fatal errors. This threshold is set to 50, which seems
    more than enough to spot a recurrent issue with a bit of context in a terminal
    to address several issues at once, without filling logs nor taking time to
    parse the file. The difference is clear now:

      $ time ./haproxy -c -f large.map 2>&1 |wc -l
      55

      real    0m0.005s
      user    0m0.004s
      sys     0m0.003s

    This may be backported to older versions without causing too many
    difficulties. However the patch will not apply as-is, it will require
    to increment the "fatal" count for each place where ERR_FATAL is set
    in the parsing loop.

diff --git a/src/cfgparse.c b/src/cfgparse.c
index 87787a362..9f44c7566 100644
--- a/src/cfgparse.c
+++ b/src/cfgparse.c
@@ -1853,6 +1853,7 @@ int readcfgfile(const char *file)
        char *outline = NULL;
        size_t outlen = 0;
        size_t outlinesize = 0;
+       int fatal = 0;

        if ((thisline = malloc(sizeof(*thisline) * linesize)) == NULL) {
                ha_alert("parsing [%s] : out of memory.\n", file);
@@ -1873,6 +1874,11 @@ next_line:

                linenum++;

+               if (fatal >= 50) {
+                       ha_alert("parsing [%s:%d]: too many fatal errors (%d), stopping now.\n", file, linenum, fatal);
+                       break;
+               }
+
                end = line + strlen(line);

                if (end-line == linesize-1 && *(end-1) != '\n') {
@@ -1887,6 +1893,7 @@ next_line:
                                ha_alert("parsing [%s:%d]: line too long, cannot allocate memory.\n",
                                         file, linenum);
                                err_code |= ERR_ALERT | ERR_FATAL;
+                               fatal++;
                                continue;
                        }

@@ -1924,6 +1931,7 @@ next_line:
                                ha_alert("parsing [%s:%d]: unmatched quote below:\n"
                                         "  %s\n  %*s\n", file, linenum, line, (int)(errptr-line+1), "^");
                                err_code |= ERR_ALERT | ERR_FATAL;
+                               fatal++;
                                goto next_line;
                        }

@@ -1931,6 +1939,7 @@ next_line:
                                ha_alert("parsing [%s:%d]: unmatched brace in environment variable name below:\n"
                                         "  %s\n  %*s\n", file, linenum, line, (int)(errptr-line+1), "^");
                                err_code |= ERR_ALERT | ERR_FATAL;
+                               fatal++;
                                goto next_line;
                        }

@@ -1938,6 +1947,7 @@ next_line:
                                ha_alert("parsing [%s:%d]: forbidden first char in environment variable name below:\n"
                                         "  %s\n  %*s\n", file, linenum, line, (int)(errptr-line+1), "^");
                                err_code |= ERR_ALERT | ERR_FATAL;
+                               fatal++;
                                goto next_line;
                        }

@@ -1952,6 +1962,7 @@ next_line:
                                ha_alert("parsing [%s:%d]: too many words, truncating at word %d, position %ld: <%s>.\n",
                                         file, linenum, arg, (long)(args[arg-1] - thisline + 1), args[arg-1]);
                                err_code |= ERR_ALERT | ERR_FATAL;
+                               fatal++;
                                goto next_line;
                        }

@@ -1962,6 +1973,7 @@ next_line:
                                        ha_alert("parsing [%s:%d]: line too long, cannot allocate memory.\n",
                                                 file, linenum);
                                        err_code |= ERR_ALERT | ERR_FATAL;
+                                       fatal++;
                                        goto next_line;
                                }
                                /* try again */
@@ -2000,6 +2012,7 @@ next_line:
                                 "supported only for options, log, busy-polling, "
                                 "set-dumpable, strict-limits, and insecure-fork-wanted.\n", file, linenum);
                        err_code |= ERR_ALERT | ERR_FATAL;
+                       fatal++;
                }

                /* detect section start */
@@ -2013,7 +2026,13 @@ next_line:
                }

                if (pcs && pcs->post_section_parser) {
-                       err_code |= pcs->post_section_parser();
+                       int status;
+
+                       status = pcs->post_section_parser();
+                       err_code |= status;
+                       if (status & ERR_FATAL)
+                               fatal++;
+
                        if (err_code & ERR_ABORT)
                                goto err;
                }
@@ -2022,8 +2041,15 @@ next_line:
                if (!cs) {
                        ha_alert("parsing [%s:%d]: unknown keyword '%s' out of section.\n", file, linenum, args[0]);
                        err_code |= ERR_ALERT | ERR_FATAL;
+                       fatal++;
                } else {
-                       err_code |= cs->section_parser(file, linenum, args, kwm);
+                       int status;
+
+                       status = cs->section_parser(file, linenum, args, kwm);
+                       err_code |= status;
+                       if (status & ERR_FATAL)
+                               fatal++;
+
                        if (err_code & ERR_ABORT)
                                goto err;
                }
